#include "cuenta.h"

TCuenta crear(int numero) {
  TCuenta c;

  c.numero = numero;
  c.saldo = 0;
  return c;
}

void depositar(TCuenta *c, double monto) {
  c->saldo = c->saldo + monto;
}

TResultado retirar(TCuenta *c, double monto) {
  if (monto > c->saldo) {
    return SALDO_INSUFICIENTE;
  }
  c->saldo = c->saldo - monto;
  return OK;
}

double obtenerSaldo(TCuenta c) {
  return c.saldo;
}

int obtenerNumero(TCuenta c) {
  return c.numero;
}

#include <stdio.h>
#include "cuenta.h"

int main() {
  TCuenta c;
  double monto;
  int numero;
  int tipo;
  int n;

  scanf("%d", &numero);
  scanf("%d", &n);
  c = crear(numero);
  for (int i = 0; i < n; i++) {
    scanf("%d", &tipo);
    scanf("%lf", &monto);
    if (tipo == 1) {
      depositar(&c, monto);
    } else {
      if (retirar(&c, monto) == SALDO_INSUFICIENTE) {
        printf("Saldo insuficiente\n");
      }
    }
  }
  printf("Cuenta %d: %.2f", obtenerNumero(c), obtenerSaldo(c));
  return 0;
}
